BEGIN;
CREATE TABLE support_cases(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,creator_id uuid NOT NULL,client_key uuid NOT NULL,number varchar(40) NOT NULL UNIQUE,title varchar(180) NOT NULL,category varchar(20) NOT NULL DEFAULT 'TECHNICAL' CHECK(category IN ('ACCOUNT','BILLING','TECHNICAL','SECURITY','OTHER')),priority varchar(10) NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('LOW','NORMAL','HIGH','URGENT')),status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','WAITING_CUSTOMER','RESOLVED','CLOSED')),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz(3) NOT NULL DEFAULT now(),updated_at timestamptz(3) NOT NULL,UNIQUE(organization_id,id),UNIQUE(organization_id,creator_id,client_key),FOREIGN KEY(organization_id,creator_id) REFERENCES memberships(organization_id,id) ON DELETE RESTRICT);
CREATE INDEX support_cases_organization_id_creator_id_updated_at_idx ON support_cases(organization_id,creator_id,updated_at);CREATE INDEX support_cases_status_updated_at_idx ON support_cases(status,updated_at);
CREATE TABLE support_messages(id uuid PRIMARY KEY,organization_id uuid NOT NULL,case_id uuid NOT NULL,client_key uuid NOT NULL,member_author_id uuid,platform_author_id uuid REFERENCES platform_accounts(id) ON DELETE RESTRICT,body varchar(10000) NOT NULL CHECK(length(body)>0),created_at timestamptz(3) NOT NULL DEFAULT now(),UNIQUE(case_id,client_key),FOREIGN KEY(organization_id,case_id) REFERENCES support_cases(organization_id,id) ON DELETE RESTRICT,FOREIGN KEY(organization_id,member_author_id) REFERENCES memberships(organization_id,id) ON DELETE RESTRICT,CHECK(num_nonnulls(member_author_id,platform_author_id)=1));
CREATE INDEX support_messages_organization_id_case_id_created_at_idx ON support_messages(organization_id,case_id,created_at);
CREATE FUNCTION work_support_can(creator uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT public.work_is_member() AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND m.user_id=NULLIF(current_setting('app.user_id',true),'')::uuid AND m.active AND (m.id=creator OR m.role IN ('ORGANIZATION_OWNER','ORGANIZATION_ADMIN')))
$$;
REVOKE ALL ON FUNCTION work_support_can(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION work_support_can(uuid) TO work_app;
ALTER TABLE support_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE support_cases FORCE ROW LEVEL SECURITY;
CREATE POLICY support_case_read ON support_cases FOR SELECT TO work_app USING(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_support_can(creator_id) OR public.platform_ops_can('support.read') OR public.platform_ops_can('support.manage'));
CREATE POLICY support_case_insert ON support_cases FOR INSERT TO work_app WITH CHECK(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.ai_owns_member(creator_id));
CREATE POLICY support_case_update ON support_cases FOR UPDATE TO work_app USING(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_support_can(creator_id) OR public.platform_ops_can('support.manage')) WITH CHECK(organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.work_support_can(creator_id) OR public.platform_ops_can('support.manage'));
GRANT SELECT,INSERT,UPDATE ON support_cases TO work_app;
ALTER TABLE support_messages ENABLE ROW LEVEL SECURITY;ALTER TABLE support_messages FORCE ROW LEVEL SECURITY;
CREATE POLICY support_message_read ON support_messages FOR SELECT TO work_app USING(EXISTS(SELECT 1 FROM public.support_cases c WHERE c.organization_id=support_messages.organization_id AND c.id=support_messages.case_id));
CREATE POLICY support_message_insert ON support_messages FOR INSERT TO work_app WITH CHECK(EXISTS(SELECT 1 FROM public.support_cases c WHERE c.organization_id=support_messages.organization_id AND c.id=support_messages.case_id) AND (platform_author_id IS NULL AND organization_id=NULLIF(current_setting('app.organization_id',true),'')::uuid AND public.ai_owns_member(member_author_id) OR member_author_id IS NULL AND platform_author_id=NULLIF(current_setting('app.platform_account_id',true),'')::uuid AND public.platform_ops_can('support.manage')));
GRANT SELECT,INSERT ON support_messages TO work_app;REVOKE UPDATE,DELETE,TRUNCATE ON support_messages FROM work_app;REVOKE DELETE,TRUNCATE ON support_cases FROM work_app;
CREATE FUNCTION support_case_identity_fixed() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$BEGIN
 IF (NEW.id,NEW.organization_id,NEW.creator_id,NEW.client_key,NEW.number,NEW.title,NEW.category,NEW.priority,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.organization_id,OLD.creator_id,OLD.client_key,OLD.number,OLD.title,OLD.category,OLD.priority,OLD.created_at) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Support case identity is immutable and requires a version increment';END IF;RETURN NEW;
END $$;
CREATE TRIGGER support_case_identity BEFORE UPDATE ON support_cases FOR EACH ROW EXECUTE FUNCTION support_case_identity_fixed();REVOKE ALL ON FUNCTION support_case_identity_fixed() FROM PUBLIC;
CREATE FUNCTION platform_support_organization(target uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET row_security=off AS $$SELECT o.name::text FROM public.organizations o WHERE o.id=target AND (public.platform_ops_can('support.read') OR public.platform_ops_can('support.manage')) AND EXISTS(SELECT 1 FROM public.support_cases c WHERE c.organization_id=o.id)$$;
REVOKE ALL ON FUNCTION platform_support_organization(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION platform_support_organization(uuid) TO work_app;
COMMIT;
